// seed: tests/seed.admin.spec.ts (admin, с #359741; было: гость) · прод, только чтение. Проект iphone (WebKit, iPhone 13 Mini, касания).
// Запуск — касание плеера (tap); проверено 2026-11-03 в WebKit: играет, audioTracks.length = 1.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, GUIDES, openGuides, videoOf, mp4Response, expectPlaying, expectPlaysWithSound, stop } from './guides.helpers';

// #359741: /guides видит только админ (гость и user уходят на /) — сессия admin, файл сессии не перезаписывается.
test.use({ storageState: '../auth/admin.json', serviceWorkers: 'block' });

test.describe('Видео-инструкции /guides — воспроизведение на iPhone', () => {
  for (const g of GUIDES) {
    test(`${g.id}: по касанию видео играет со звуком, WebKit видит звуковую дорожку #8790d6 @iphone @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openGuides(page);
      const video = videoOf(page, g);

      const resp = mp4Response(page, g);
      // tap сам прокручивает к плееру и переискивает его, если админская страница перерисовалась после чтения роли (#359741).
      await video.tap();
      const r = await resp;
      await expectPlaying(video, 2, g.id);
      await expectPlaysWithSound(video, r, g);
      const tracks = await video.evaluate((v) => {
        const t = (v as HTMLVideoElement & { audioTracks?: { length: number } }).audioTracks;
        return t ? t.length : -1;
      });
      expect(tracks, `${g.id}: video.audioTracks.length (-1 — API нет)`).toBeGreaterThanOrEqual(1);
      await stop(video);
    });
  }
});
